<script setup>
import {computed,onMounted,reactive,ref,watch} from "vue";import{useRoute}from"vue-router";import{call,canAccess}from"../api";import AppModal from"../components/AppModal.vue";import ListPageHeader from"../components/ListPageHeader.vue";import SmartFilterBar from"../components/SmartFilterBar.vue";import SmartDataTable from"../components/SmartDataTable.vue";
const route=useRoute(),kind=computed(()=>route.meta.kind||"overview"),rows=ref([]),totals=ref({}),loading=ref(true),error=ref(""),selectedDoc=ref(null),token=ref(null);const options=reactive({entities:[],points:[],cashiers:[]});const today=new Date().toISOString().slice(0,10),month=new Date(new Date().getFullYear(),new Date().getMonth(),1).toISOString().slice(0,10);const filters=reactive({from_date:month,to_date:today,business_entity:"",business_point:"",cashier:"",search:"",status:"",movement_type:"",action_type:""});
const cfg={overview:{title:"Точки продаж",desc:"Текущая работа касс и продажи по всей сети"},shifts:{title:"Смены",desc:"Выручка, возвраты, скидки и действия за каждую смену"},receipts:{title:"Продажи",desc:"Все чеки, оплаты, товары и клиенты"},returns:{title:"Возвраты",desc:"Возвратные чеки и связь с исходной продажей"},cash:{title:"Внесения и выплаты",desc:"Движение наличных между кассой ИП и кассой точки"},actions:{title:"Действия кассира",desc:"Неизменяемый журнал операций и контрольных событий"},integration:{title:"Подключение кассы",desc:"Безопасный обмен с Windows-программой каждой точки"}};
const pointMap=computed(()=>Object.fromEntries(options.points.map(x=>[x.name,x.point_name]))),employeeMap=computed(()=>Object.fromEntries(options.cashiers.map(x=>[x.name,x.full_name]))),points=computed(()=>options.points.filter(x=>!filters.business_entity||x.business_entity===filters.business_entity));const money=v=>`${new Intl.NumberFormat("ru-RU",{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(v||0))} ₽`;const date=v=>v?new Intl.DateTimeFormat("ru-RU",{dateStyle:"short",timeStyle:"short"}).format(new Date(v)):"—";const actionLabel=v=>({OPEN_SHIFT:"Открытие смены",CLOSE_SHIFT:"Закрытие смены",SALE:"Продажа",RETURN:"Возврат",DEPOSIT:"Внесение",WITHDRAWAL:"Выплата",CANCEL_RECEIPT:"Отмена чека",CANCEL_CASH_MOVEMENT:"Отмена кассовой операции",REMOVE_ITEM:"Удаление позиции",PRICE_OVERRIDE:"Свободная цена",DISCOUNT:"Скидка",REVIEW_RECEIVED:"Получен отзыв",CLUB_REGISTRATION:"Регистрация в клубе",GIFT_ORDER:"Заказ подарка"}[v]||v);
const columns=computed(()=>({shifts:[c("name","Смена"),c("shift_type","Тип"),c("opened_at","Открыта","date"),c("closed_at","Закрыта","date"),c("business_point","Точка","point"),c("cashier","Кассир","employee"),c("receipt_count","Чеки"),c("gross_sales","Выручка","money"),c("returns_total","Возвраты","money"),c("net_sales","Чистая выручка","money"),c("average_check","Средний чек","money"),c("discounts_total","Скидки","money"),c("discounted_receipt_count","Чеков со скидкой"),c("discount_conversion","Конверсия скидки","percent"),c("reviews_count","Отзывы"),c("club_registrations","Клуб"),c("gift_orders","Подарки"),c("status","Статус")],receipts:receiptCols(),returns:receiptCols(),cash:[c("name","№"),c("posting_datetime","Время","date"),c("movement_type","Операция","movement"),c("business_point","Точка","point"),c("cashier","Кассир","employee"),c("from_cash","Из кассы"),c("to_cash","В кассу"),c("amount","Сумма","money"),c("reason","Комментарий")],actions:[c("action_datetime","Время","date"),c("action_type","Действие","action"),c("business_point","Точка","point"),c("cashier","Кассир","employee"),c("shift","Смена"),c("metric_value","Количество"),c("details","Подробности")]}[kind.value]||[]));
function c(key,label,format=""){return{key,label,format}}function receiptCols(){return[c("name","Чек"),c("posting_datetime","Время","date"),c("business_point","Точка","point"),c("cashier","Кассир","employee"),c("client","Клиент"),c("payments","Оплата","payment"),c("gross_amount","До скидки","money"),c("discount_amount","Скидка","money"),c("total_amount","Итого","money"),c("cost_amount","Себестоимость","money"),c("profit_amount","Прибыль","money")]}function fmt(v,col){if(col.format==="money")return money(v);if(col.format==="percent")return `${new Intl.NumberFormat("ru-RU",{maximumFractionDigits:1}).format(Number(v||0))}%`;if(col.format==="date")return date(v);if(col.format==="point")return pointMap.value[v]||v||"—";if(col.format==="employee")return employeeMap.value[v]||v||"—";if(col.format==="movement")return v==="Deposit"?"Внесение":"Выплата";if(col.format==="action")return actionLabel(v);if(col.format==="payment")return Object.entries(v||{}).map(([k,x])=>`${k==="Cash"?"Нал.":k==="Card"?"Карта":"QR"} ${money(x)}`).join(" · ")||"—";return v??"—"}
const filterFields=computed(()=>{const result=[{key:"search",label:"Поиск",placeholder:"Номер или комментарий",wide:true},{key:"from_date",label:"Период с",type:"date"},{key:"to_date",label:"Период по",type:"date"},{key:"business_entity",label:"Юридическое лицо",type:"select",allLabel:"Все ИП",options:options.entities.map(x=>({value:x.name,label:x.short_name}))},{key:"business_point",label:"Точка",type:"select",allLabel:"Все точки",options:points.value.map(x=>({value:x.name,label:x.point_name}))}];if(["shifts","actions"].includes(kind.value))result.push({key:"cashier",label:"Кассир",type:"select",allLabel:"Все кассиры",options:options.cashiers.map(x=>({value:x.name,label:x.full_name}))});if(kind.value==="shifts")result.push({key:"status",label:"Статус",type:"select",allLabel:"Все статусы",options:[{value:"Open",label:"Открыта"},{value:"Closed",label:"Закрыта"},{value:"Cancelled",label:"Отменена"}]});if(kind.value==="cash")result.push({key:"movement_type",label:"Операция",type:"select",allLabel:"Все операции",options:[{value:"Deposit",label:"Внесения"},{value:"Withdrawal",label:"Выплаты"}]});if(kind.value==="actions")result.push({key:"action_type",label:"Действие",type:"select",allLabel:"Все действия",options:["OPEN_SHIFT","CLOSE_SHIFT","REMOVE_ITEM","PRICE_OVERRIDE","DISCOUNT","REVIEW_RECEIVED","CLUB_REGISTRATION","GIFT_ORDER"].map(value=>({value,label:actionLabel(value)}))});return result});
const tableColumns=computed(()=>columns.value.map(col=>({...col,primary:col.key==="name",number:["money","percent"].includes(col.format),format:value=>fmt(value,col)})));
const tableTotals=computed(()=>{const result={};for(const col of columns.value){if(col.format==="money"&&!['average_check'].includes(col.key))result[col.key]=rows.value.reduce((sum,row)=>sum+Number(row[col.key]||0),0);else if(["receipt_count","reviews_count","club_registrations","gift_orders","metric_value"].includes(col.key))result[col.key]=rows.value.reduce((sum,row)=>sum+Number(row[col.key]||0),0)}return result});
async function init(){try{Object.assign(options,await call("raspechatka.api.sales.get_sales_options"));await load()}catch(e){error.value=e.message;loading.value=false}}
async function load(){loading.value=true;error.value="";selectedDoc.value=null;try{const common={from_date:filters.from_date,to_date:filters.to_date,business_entity:filters.business_entity,business_point:filters.business_point};let method="get_points_overview",params=common;if(kind.value==="shifts"){method="get_shifts";params={...common,cashier:filters.cashier,status:filters.status,search:filters.search,limit_page_length:10000}}if(kind.value==="receipts"||kind.value==="returns"){method="get_receipts";params={...common,cashier:filters.cashier,search:filters.search,receipt_type:kind.value==="returns"?"Return":"Sale",limit_page_length:10000}}if(kind.value==="cash"){method="get_cash_movements";params={...common,movement_type:filters.movement_type,search:filters.search}}if(kind.value==="actions"){method="get_cashier_actions";params={...common,cashier:filters.cashier,action_type:filters.action_type}}if(kind.value==="integration"){method="get_connections";params={}}const result=await call(`raspechatka.api.sales.${method}`,params);rows.value=result.rows||[];totals.value=result.totals||{}}catch(e){error.value=e.message}finally{loading.value=false}}
async function openRow(row){if(kind.value==="shifts")selectedDoc.value=await call("raspechatka.api.sales.get_shift",{name:row.name});if(kind.value==="receipts"||kind.value==="returns")selectedDoc.value=await call("raspechatka.api.sales.get_receipt",{name:row.name})}async function provision(point,rotate=false){const result=await call("raspechatka.api.sales.provision_connection",{business_point:point,rotate:rotate?1:0},{method:"POST"});token.value=result;await load()}watch(kind,load);onMounted(init);
</script>
<template><section class="page sales-page"><ListPageHeader :title="cfg[kind].title" />
<SmartFilterBar v-if="kind!=='integration'" :key="kind" :model-value="filters" :fields="filterFields" :view-key="`sales.${kind}`" @update:model-value="Object.assign(filters,$event)" @apply="load" @reset="load" />
<div v-if="loading" class="table-message"><span class="loader"></span><span>Загружаем продажи…</span></div><div v-else-if="error" class="table-message error-message"><strong>Не удалось загрузить данные</strong><span>{{error}}</span><button @click="load">Повторить</button></div>
<template v-else-if="kind==='overview'"><div class="sales-kpis"><article class="accent"><small>ЧИСТАЯ ВЫРУЧКА</small><b>{{money(totals.revenue)}}</b><span>за выбранный период</span></article><article><small>ЧЕКОВ</small><b>{{totals.receipt_count||0}}</b><span>во всех точках</span></article><article><small>СКИДКИ</small><b>{{money(totals.discounts)}}</b><span>включая отзывы и клуб</span></article><article><small>ВОЗВРАТЫ</small><b>{{money(totals.returns)}}</b><span>вычтены из выручки</span></article></div><div class="point-grid"><article v-for="r in rows" :key="r.name"><header><div><small>{{r.city}}</small><h2>{{r.point_name}}</h2></div><span class="connection-status" :class="{connected:r.connection?.status==='В сети',error:r.connection?.status==='Ошибка'}">{{r.connection?.status||'Не подключена'}}</span></header><div class="point-stats"><span>Выручка <b>{{money(r.revenue)}}</b></span><span>Чеки <b>{{r.receipt_count}}</b></span><span>Средний чек <b>{{money(r.average_check)}}</b></span><span>Денег в кассе <b>{{money(r.cash_balance)}}</b></span></div><footer><span>{{r.open_shift?'Смена открыта '+date(r.open_shift.opened_at):'Нет открытой смены'}}</span><span>Синхронизация: {{date(r.connection?.last_sync_at)}}</span></footer></article></div></template>
<template v-else-if="kind==='integration'"><div class="bank-security-note"><span>✓</span><div><b>Токен показывается один раз</b><p>Каждая касса привязана к одной точке. Пакеты принимаются идемпотентно: повторная отправка не создаёт дублей.</p></div></div><div class="bank-connections"><article v-for="p in options.points" :key="p.name"><div><small>{{p.city}}</small><h3>{{p.point_name}}</h3><span>{{rows.find(x=>x.business_point===p.name)?.device_id||'Касса ещё не зарегистрирована'}}</span></div><span class="connection-status" :class="{connected:rows.find(x=>x.business_point===p.name)?.status==='В сети'}">{{rows.find(x=>x.business_point===p.name)?.status||'Не подключена'}}</span><div class="connection-actions"><button class="button button-primary" @click="provision(p.name,!!rows.find(x=>x.business_point===p.name))">{{rows.find(x=>x.business_point===p.name)?'Перевыпустить токен':'Подключить кассу'}}</button></div></article></div><div v-if="token" class="token-panel"><b>Сохраните реквизиты подключения сейчас</b><code>Device ID: {{token.device_id}}<br>Token: {{token.token}}</code><button @click="token=null">Я сохранил</button></div></template>
<template v-else><SmartDataTable :rows="rows" :columns="tableColumns" :totals="tableTotals" :view-key="`sales.${kind}`" empty-title="Данных пока нет" empty-text="Они появятся после первой синхронизации кассовой программы." @open="openRow" /></template>
<AppModal v-if="selectedDoc" :title="selectedDoc.receipt_type?(selectedDoc.receipt_type==='Return'?'Возврат ':'Продажа ')+selectedDoc.name:'Смена '+selectedDoc.name" wide @close="selectedDoc=null"><template v-if="selectedDoc.receipt_type"><div class="document-summary"><span>Точка <b>{{pointMap[selectedDoc.business_point]}}</b></span><span>Кассир <b>{{employeeMap[selectedDoc.cashier]||'—'}}</b></span><span>Время <b>{{date(selectedDoc.posting_datetime)}}</b></span><span>Итого <b>{{money(selectedDoc.total_amount)}}</b></span></div><table><thead><tr><th>Наименование</th><th>Количество</th><th>Цена</th><th>Скидка</th><th>Сумма</th><th>Себестоимость</th></tr></thead><tbody><tr v-for="x in selectedDoc.items" :key="x.name"><td class="item-name">{{x.item_name}}</td><td>{{x.quantity}} {{x.uom}}</td><td>{{money(x.unit_price)}}</td><td>{{money(x.discount_amount)}}</td><td>{{money(x.line_total)}}</td><td>{{money(x.cost_amount)}}</td></tr></tbody></table></template><template v-else><div class="shift-detail-kpis"><span>Чистая выручка <b>{{money(selectedDoc.net_sales)}}</b></span><span>Чеков <b>{{selectedDoc.receipt_count}}</b></span><span>Средний чек <b>{{money(selectedDoc.average_check)}}</b></span><span>Касса <b>{{money(selectedDoc.expected_cash)}}</b></span></div><h3>Документы смены</h3><table><thead><tr><th>Время</th><th>Тип</th><th>Оплата</th><th>Скидка</th><th>Итого</th></tr></thead><tbody><tr v-for="x in selectedDoc.receipts" :key="x.name"><td>{{date(x.posting_datetime)}}</td><td>{{x.receipt_type==='Sale'?'Продажа':'Возврат'}}</td><td>{{fmt(x.payments,{format:'payment'})}}</td><td>{{money(x.discount_amount)}}</td><td>{{money(x.total_amount)}}</td></tr></tbody></table></template></AppModal></section></template>
